import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "~": 4,
        ":": 5,
    }
    tokenizer = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/():,=<>]")

    def parse(expression):
        nodes = []
        operators = []
        pending_function = None
        expect_operand = True

        def reduce_operator():
            operator = operators.pop()
            if operator == "~":
                nodes.append(("neg", nodes.pop()))
                return

            right = nodes.pop()
            left = nodes.pop()
            if operator == ":":
                nodes.append(("range", left[1], right[1]))
            else:
                nodes.append(("binary", operator, left, right))

        for token in tokenizer.findall(expression):
            if token[0].isdigit():
                nodes.append(("number", int(token)))
                expect_operand = False
            elif token in functions:
                pending_function = token
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            elif token == "(":
                operators.append(("(", pending_function, len(nodes)))
                pending_function = None
                expect_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()

                _, function, start = operators.pop()
                if function is not None:
                    arguments = tuple(nodes[start:])
                    del nodes[start:]
                    nodes.append(("call", function, arguments))
                expect_operand = False
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                expect_operand = True
            else:
                operator = "~" if token == "-" and expect_operand else token
                while operators and isinstance(operators[-1], str):
                    previous = operators[-1]
                    if precedence[previous] < precedence[operator]:
                        break
                    if (
                        operator == "~"
                        and precedence[previous] == precedence[operator]
                    ):
                        break
                    reduce_operator()

                operators.append(operator)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    cache = {}
    active = set()

    # Each generator yields a node to evaluate. An explicit stack below
    # drives them, so neither formulas nor reference chains use recursion.
    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]

        if kind == "reference":
            name = node[1]
            if name not in cells:
                return 0
            if name in cache:
                return cache[name]
            if name in active:
                return "#CYCLE!"

            active.add(name)
            content = cells[name]
            if content.startswith("="):
                value = yield parse(content[1:])
            else:
                value = int(content)

            active.remove(name)
            cache[name] = value
            return value

        if kind == "neg":
            value = yield node[1]
            return value if isinstance(value, str) else -value

        if kind == "binary":
            _, operator, left_node, right_node = node

            left = yield left_node
            if isinstance(left, str):
                return left

            right = yield right_node
            if isinstance(right, str):
                return right

            if operator == "+":
                return left + right
            if operator == "-":
                return left - right
            if operator == "*":
                return left * right
            if operator == "/":
                if right == 0:
                    return "#DIV/0!"
                quotient = abs(left) // abs(right)
                return -quotient if (left < 0) != (right < 0) else quotient
            if operator == "=":
                return left == right
            if operator == "<>":
                return left != right
            if operator == "<":
                return left < right
            if operator == "<=":
                return left <= right
            if operator == ">":
                return left > right
            return left >= right

        _, function, arguments = node

        if function == "IF":
            condition = yield arguments[0]
            if isinstance(condition, str):
                return condition
            branch = arguments[1] if condition else arguments[2]
            return (yield branch)

        result = 0 if function == "SUM" else None

        for argument in arguments:
            if argument[0] == "range":
                first, last = argument[1], argument[2]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))

                children = (
                    ("reference", name)
                    for row in range(row1, row2 + 1)
                    for col in range(col1, col2 + 1)
                    if (name := chr(col) + str(row)) in cells
                )
            else:
                children = (argument,)

            for child in children:
                value = yield child
                if isinstance(value, str):
                    return value

                if function == "SUM":
                    result += value
                elif result is None:
                    result = value
                elif function == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)

        return 0 if result is None else result

    for name in cells:
        if name in cache:
            continue

        stack = [evaluate(("reference", name))]
        value = None

        while stack:
            try:
                child = stack[-1].send(value)
            except StopIteration as finished:
                value = finished.value
                stack.pop()
            else:
                stack.append(evaluate(child))
                value = None

    return {name: cache[name] for name in cells}
